insert into sources (code, name, description, kind, base_url, docs_url, auth, countries, regions, license, attribution, retention_days, redistributable, published_by) values
  ('ban', 'Base Adresse Nationale', 'The national address register: search as you type and reverse geocoding, with house-number precision. Read by packages/connectors/ban.', 'api', 'https://api-adresse.data.gouv.fr/', 'https://adresse.data.gouv.fr/outils/api-doc/adresse', 'none', array['FR']::text[], '{}'::text[], 'Licence Ouverte 2.0', '© BAN — Base Adresse Nationale', null, true, 'pack:fr'),
  ('bd_topo', 'BD TOPO (IGN)', 'The national topographic database: buildings with height and use, roads, land use, administrative limits.', 'file', 'https://geoservices.ign.fr/bdtopo', 'https://geoservices.ign.fr/documentation/donnees/vecteur/bdtopo', 'none', array['FR']::text[], '{}'::text[], 'Licence Ouverte 2.0', '© IGN', null, true, 'pack:fr'),
  ('cadastre', 'Cadastre (PCI vecteur, Etalab)', 'Parcels, building footprints and sections of the cadastre, by municipality, as GeoJSON.', 'file', 'https://cadastre.data.gouv.fr/', 'https://cadastre.data.gouv.fr/datasets/cadastre-etalab', 'none', array['FR']::text[], '{}'::text[], 'Licence Ouverte 2.0', '© DGFiP — Etalab', null, true, 'pack:fr'),
  ('enedis_data_connect', 'Enedis Data Connect', 'A customer''s meter data (daily index, 30-minute load curve, contract) read by a third party with the customer''s consent, per PRM. Kept for the consent''s duration, never passed on.', 'api', 'https://datahub-enedis.fr/data-connect/', null, 'mandate', array['FR']::text[], '{}'::text[], 'Enedis Data Connect terms', '© Enedis', null, false, 'pack:fr'),
  ('enedis_open_data', 'Enedis Open Data', 'Aggregated consumption and production by municipality, grid capacities, energy sharing operations in service.', 'api', 'https://data.enedis.fr/', null, 'none', array['FR']::text[], '{}'::text[], 'Licence Ouverte 2.0', '© Enedis', null, true, 'pack:fr'),
  ('fr_bofip_vat_energy_subscriptions', 'BOFiP — VAT rate on electricity and gas subscriptions (BOI-RES-TVA-000209)', 'The tax administration''s answer on the end of the reduced VAT rate on subscriptions of electricity and natural gas up to 36 kVA.', 'text', 'https://bofip.impots.gouv.fr/node/383125', null, 'none', array['FR']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:fr'),
  ('fr_code_travail_voltage_domains', 'Code du travail, article R. 4226-2 — voltage domains', 'The article that defines the voltage domains of an electrical installation: very low, low and high voltage A and B.', 'text', 'https://code.travail.gouv.fr/code-du-travail/r4226-2', null, 'none', array['FR']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:fr'),
  ('fr_cre_offpeak_hours', 'CRE — questions and answers on peak and off-peak hours (6 February 2025)', 'The regulator''s answers on how off-peak hours are placed and on their reform under TURPE 7.', 'text', 'https://www.cre.fr/fileadmin/Documents/Communiques_de_presse/2025/250206_FAQ_HP-HC.pdf', null, 'none', array['FR']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:fr'),
  ('fr_cre_zni', 'CRE — the energy transition in the non-interconnected zones', 'The regulator''s page on the zones not connected to the continental grid: Corsica, the overseas departments and islands.', 'text', 'https://www.cre.fr/electricite/transition-energetique-dans-les-zni.html', null, 'none', array['FR']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:fr'),
  ('fr_enedis_load_curve_collection', 'Enedis — activating and deactivating the collection of load curves', 'The distribution operator''s sheet on the collection of a meter''s load curve: its step and history by meter size.', 'text', 'https://www.enedis.fr/media/4543/download', null, 'none', array['FR']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:fr'),
  ('fr_entsoe_eic_codes', 'ENTSO-E — list of Y EIC codes (areas)', 'The list of area codes of the European electricity market, with their functions: bidding zone, control area, scheduling area.', 'text', 'https://eepublicdownloads.blob.core.windows.net/cio-lio/csv/Y_eicCodes.csv', null, 'none', array['FR']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:fr'),
  ('fr_eurostat_business_prices', 'Eurostat — electricity prices components for non-household consumers, annual (nrg_pc_205_c)', 'Yearly electricity prices of non-household consumers by consumption band and component.', 'text', 'https://ec.europa.eu/eurostat/databrowser/view/nrg_pc_205_c/default/table', null, 'none', array['FR']::text[], '{}'::text[], 'CC-BY-4.0', '© European Union, Eurostat', null, true, 'pack:fr'),
  ('fr_eurostat_household_prices', 'Eurostat — electricity prices components for household consumers, annual (nrg_pc_204_c)', 'Yearly electricity prices of households by consumption band and component: energy and supply, network costs, taxes and levies, VAT.', 'text', 'https://ec.europa.eu/eurostat/databrowser/view/nrg_pc_204_c/default/table', null, 'none', array['FR']::text[], '{}'::text[], 'CC-BY-4.0', '© European Union, Eurostat', null, true, 'pack:fr'),
  ('fr_rte_bilan_2024', 'RTE — Bilan électrique 2024', 'The transmission operator''s yearly report on the French electricity system for 2024.', 'text', 'https://analysesetdonnees.rte-france.com/bilan-electrique-2024/prix', null, 'none', array['FR']::text[], '{}'::text[], 'Public data, reuse with attribution (RTE legal notice)', '© RTE — Bilan électrique 2024', null, true, 'pack:fr'),
  ('fr_rte_bilan_2025', 'RTE — Bilan électrique 2025', 'The transmission operator''s yearly report on the French electricity system for 2025.', 'text', 'https://analysesetdonnees.rte-france.com/bilan-electrique-2025/emissions', null, 'none', array['FR']::text[], '{}'::text[], 'Public data, reuse with attribution (RTE legal notice)', '© RTE — Bilan électrique 2025', null, true, 'pack:fr'),
  ('geo_api_gouv', 'API Découpage administratif', 'Municipalities, departments and regions, with their codes and boundaries.', 'api', 'https://geo.api.gouv.fr/', 'https://geo.api.gouv.fr/decoupage-administratif', 'none', array['FR']::text[], '{}'::text[], 'Licence Ouverte 2.0', '© Etalab', null, true, 'pack:fr'),
  ('insee_cog', 'Code officiel géographique (INSEE)', 'The statistics office''s official list of municipalities, departments and regions with their codes, published every year.', 'file', 'https://www.insee.fr/fr/information/2560452', null, 'none', array['FR']::text[], '{}'::text[], 'Licence Ouverte 2.0', '© INSEE', null, true, 'pack:fr'),
  ('odre', 'Open Data Réseaux Énergies', 'Datasets of the French energy networks: generation, consumption, exchanges, operators'' areas, energy communities.', 'api', 'https://odre.opendatasoft.com/', null, 'none', array['FR']::text[], '{}'::text[], 'Licence Ouverte 2.0', '© ODRÉ', null, true, 'pack:fr'),
  ('rnb', 'Référentiel National des Bâtiments', 'One stable identifier per building, with its footprint and the addresses and parcels it links to.', 'api', 'https://rnb-api.beta.gouv.fr/', 'https://rnb.beta.gouv.fr/', 'none', array['FR']::text[], '{}'::text[], 'Licence Ouverte 2.0', '© RNB', null, true, 'pack:fr'),
  ('sirene', 'API Sirene (INSEE)', 'The register of companies and establishments: SIREN, SIRET, legal form, activity, addresses.', 'api', 'https://api.insee.fr/', 'https://www.sirene.fr/', 'api_key', array['FR']::text[], '{}'::text[], 'Licence Ouverte 2.0', '© INSEE', null, true, 'pack:fr')
insert into identifier_schemes (code, name, description, pattern, url_template, source_code, published_by) values
  ('ban_address', 'BAN address', 'The identifier of an address in the Base Adresse Nationale: municipality code, street, number.', '^[0-9][0-9abAB][0-9]{3}_[0-9a-z]+_[0-9a-z_]+$', 'https://adresse.data.gouv.fr/base-adresse-nationale/{value}', 'ban', 'pack:fr'),
  ('insee', 'Code INSEE', 'The code of a municipality in the official geographic code of the statistics office (code commune INSEE): the level at which the distribution operator, planning rules and most datasets are decided. It is not the postal code.', '^[0-9][0-9AB][0-9]{3}$', null, 'insee_cog', 'pack:fr'),
  ('parcelle', 'Cadastral parcel', 'The 14-character identifier of a cadastral parcel: municipality (5), prefix (3), section (2), number (4).', '^[0-9][0-9AB][0-9]{3}[0-9A-Z]{3}[0-9A-Z]{2}[0-9]{4}$', 'https://cadastre.data.gouv.fr/map?parcelleId={value}', 'cadastre', 'pack:fr'),
  ('prm', 'PRM / PDL', 'The 14-digit identifier of a metering point of the French distribution grid (point de référence mesure, also point de livraison), issued by the distribution operator of the connection.', '^[0-9]{14}$', null, null, 'pack:fr'),
  ('rnb_id', 'RNB building', 'The 12-character identifier of a building in the Référentiel National des Bâtiments.', '^[A-Z0-9]{12}$', 'https://rnb.beta.gouv.fr/batiments/{value}', 'rnb', 'pack:fr'),
  ('siren', 'SIREN', 'The 9-digit identifier of a company in the national register.', '^[0-9]{9}$', 'https://annuaire-entreprises.data.gouv.fr/entreprise/{value}', 'sirene', 'pack:fr'),
  ('siret', 'SIRET', 'The 14-digit identifier of an establishment: the SIREN of its company and a 5-digit number.', '^[0-9]{14}$', 'https://annuaire-entreprises.data.gouv.fr/etablissement/{value}', 'sirene', 'pack:fr')
