insert into grid.operators (code, name, kind, country, regions, coverage, website, data_hub_url, identifier_scheme, description, published_by) values
  ('edf_sei', 'EDF Systèmes Énergétiques Insulaires', 'island', 'FR', array['FR-2A', 'FR-2B', 'FR-971', 'FR-972', 'FR-973', 'FR-974']::text[], 'Corsica and the overseas departments but Mayotte, not interconnected with the mainland.', 'https://www.edf.fr/sei', null, 'prm', 'Distribution and system operation of the non-interconnected zones (zones non interconnectées).', 'pack:fr'),
  ('edm', 'Électricité de Mayotte', 'island', 'FR', array['FR-976']::text[], 'Mayotte, not interconnected.', 'https://www.electricitedemayotte.com/', null, null, 'Producer, distribution operator and supplier of Mayotte.', 'pack:fr'),
  ('enedis', 'Enedis', 'dso', 'FR', '{}'::text[], 'About 95 % of the distribution of mainland France; the rest is served by local distribution companies.', 'https://www.enedis.fr/', 'https://datahub-enedis.fr/', 'prm', 'The main distribution operator: connection, Linky meters, meter data (Data Connect), the operator side of collective self-consumption.', 'pack:fr'),
  ('es_reseaux', 'Strasbourg Électricité Réseaux', 'dso', 'FR', array['FR-67']::text[], 'Strasbourg and about 400 municipalities of the Bas-Rhin.', 'https://www.es-reseaux.fr/', null, 'prm', 'The largest local distribution company (entreprise locale de distribution).', 'pack:fr'),
  ('geg_reseaux', 'GreenAlp', 'dso', 'FR', array['FR-38']::text[], 'Grenoble and its surroundings.', 'https://www.greenalp.fr/', null, 'prm', 'The distribution subsidiary of Gaz Électricité de Grenoble.', 'pack:fr'),
  ('geredis', 'Gérédis', 'dso', 'FR', array['FR-79']::text[], 'The Deux-Sèvres department.', 'https://www.geredis.fr/', null, 'prm', 'Local distribution company of the Deux-Sèvres.', 'pack:fr'),
  ('rte', 'RTE', 'tso', 'FR', '{}'::text[], 'The transmission grid of mainland France.', 'https://www.rte-france.com/', 'https://data.rte-france.com/', null, 'The transmission system operator: the high-voltage grid, balancing, the connection of large plants, the public data of the system.', 'pack:fr'),
  ('srd', 'SRD', 'dso', 'FR', array['FR-86']::text[], 'Most of the Vienne department outside Poitiers.', 'https://www.srd-energies.fr/', null, 'prm', 'Local distribution company of the Vienne.', 'pack:fr'),
  ('urm', 'URM', 'dso', 'FR', array['FR-57']::text[], 'Metz and its surroundings.', 'https://www.urm-metz.fr/', null, 'prm', 'Local distribution company of Metz.', 'pack:fr')
